package com.medflow.auth.security;
import com.medflow.auth.repository.UserAccountRepository; import io.jsonwebtoken.JwtException; import jakarta.servlet.*; import jakarta.servlet.http.*; import java.io.IOException; import java.util.List; import java.util.UUID; import org.springframework.http.HttpHeaders; import org.springframework.lang.NonNull; import org.springframework.security.authentication.UsernamePasswordAuthenticationToken; import org.springframework.security.core.authority.SimpleGrantedAuthority; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.stereotype.Component; import org.springframework.web.filter.OncePerRequestFilter;
@Component public class JwtAuthenticationFilter extends OncePerRequestFilter {
 private final JwtService jwt; private final UserAccountRepository users; public JwtAuthenticationFilter(JwtService j,UserAccountRepository u){jwt=j;users=u;}
 @Override protected void doFilterInternal(@NonNull HttpServletRequest req,@NonNull HttpServletResponse res,@NonNull FilterChain chain)throws ServletException,IOException{String h=req.getHeader(HttpHeaders.AUTHORIZATION);if(h!=null&&h.startsWith("Bearer ")&&SecurityContextHolder.getContext().getAuthentication()==null){try{UUID userId=UUID.fromString(jwt.subject(h.substring(7)));users.findById(userId).filter(x->x.isEnabled()).ifPresent(u->SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken(u.getEmail(),null,List.of(new SimpleGrantedAuthority("ROLE_"+u.getRole().name())))));}catch(JwtException|IllegalArgumentException ignored){}}chain.doFilter(req,res);}
}
